<script setup>
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { auth,loadAuth,signIn } from '../auth'
const router=useRouter(),username=ref(''),password=ref(''),displayName=ref(''),confirm=ref(''),busy=ref(false),ready=ref(false),error=ref('')
onMounted(async()=>{try{await loadAuth();ready.value=true;if(auth.user)router.replace('/cockpit')}catch{error.value='登录服务暂时不可用，请稍后重试'}})
async function submit(){if(busy.value||!ready.value)return;const wasSetup=auth.needsSetup;try{await loadAuth()}catch{ready.value=false;error.value='登录服务暂时不可用，请刷新后重试';return}if(auth.needsSetup!==wasSetup){error.value=auth.needsSetup?'系统尚未创建账号，请填写显示名称并设置管理员密码。':'系统已完成初始化，请使用已有账号登录。';return}if(auth.needsSetup&&password.value!==confirm.value){error.value='两次输入的密码不一致';return}busy.value=true;error.value='';try{await signIn({username:username.value,password:password.value,display_name:displayName.value},auth.needsSetup);password.value='';confirm.value='';await router.replace('/cockpit')}catch(e){error.value=typeof e.message==='string'?e.message:'请检查输入'}finally{busy.value=false}}
</script>
<template><main class="login-page"><section class="login-story"><div class="login-brand">r· <span>巡境</span></div><div><small>ROBOT OPERATIONS</small><h1>每一次巡检，<br>都有迹可循。</h1><p>连接设备、任务与现场，<br>让发现的问题得到妥善处理。</p><div class="login-map"><i></i><i></i><i></i><span>●</span></div></div><footer>Factory · L1 <span>智能巡检工作空间</span></footer></section><section class="login-form"><div class="login-card"><small class="eyebrow">{{ auth.needsSetup?'WELCOME TO YOUR WORKSPACE':'WELCOME BACK' }}</small><h2>{{ auth.needsSetup?'创建管理员':'登录巡境' }}</h2><p>{{ auth.needsSetup?'首次使用，请为这个工作空间创建管理员账号。':'使用你的账号进入巡检工作空间。' }}</p><form @submit.prevent="submit"><label v-if="auth.needsSetup">显示名称<el-input v-model="displayName" maxlength="80" autocomplete="name" placeholder="例如：巡检负责人" required/></label><label>用户名<el-input v-model="username" maxlength="32" autocomplete="username" placeholder="3–32 位字母、数字或 . _ -" required/></label><label>密码<el-input v-model="password" type="password" show-password maxlength="128" :autocomplete="auth.needsSetup?'new-password':'current-password'" :placeholder="auth.needsSetup?'至少 12 个字符':'输入密码'" required/></label><label v-if="auth.needsSetup">确认密码<el-input v-model="confirm" type="password" show-password maxlength="128" autocomplete="new-password" required/></label><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button type="primary" native-type="submit" :loading="busy" :disabled="!ready">{{ !ready?'正在连接登录服务…':auth.needsSetup?'创建并进入工作空间':'登录工作空间' }} ↗</el-button></form><div class="login-note">{{ auth.needsSetup?'管理员可创建操作员与查看账号。':'账号由管理员分配，忘记密码请联系管理员。' }}</div></div></section></main></template>
<style scoped>.login-page{min-height:100vh;display:grid;grid-template-columns:45% 55%;background:#f7f8f3}.login-story{background:#193c32;color:#e1edc7;padding:54px 65px;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden}.login-brand{font-size:39px;font-weight:600}.login-brand span{font-size:26px;margin-left:10px}.login-story small{font-size:10px;letter-spacing:2px;color:#a0b89a}.login-story h1{font-size:46px;line-height:1.5;font-weight:500;letter-spacing:2px;margin:20px 0}.login-story p{font-size:14px;line-height:2;color:#a5b89a}.login-story footer{font-size:11px;color:#90a98d;display:flex;justify-content:space-between;gap:20px}.login-map{height:120px;margin:40px 0;position:relative;background-image:radial-gradient(#b9d09c44 1px,transparent 1px);background-size:18px 18px}.login-map i{position:absolute;width:29%;height:60px;top:25px;border:1px solid #aec89655;border-radius:7px}.login-map i:nth-child(2){left:34%}.login-map i:nth-child(3){left:68%}.login-map span{position:absolute;left:50%;top:50px;color:#d2e9ab}.login-form{display:flex;align-items:center;justify-content:center;padding:50px 28px}.login-card{width:365px;max-width:100%}.login-card h2{font-size:30px;font-weight:550;margin:16px 0}.login-card>p{color:#8c9a80;font-size:12px;line-height:1.8;margin-bottom:30px}.login-card label{display:block;font-size:12px;color:#677d5d;margin:18px 0}.login-card .el-input{margin-top:10px}.login-card :deep(.el-input__wrapper){min-height:40px;background:white}.login-card form>.el-button{width:100%;height:44px;margin-top:18px}.login-note{border-top:1px solid #e1e7da;margin-top:30px;padding-top:20px;font-size:11px;color:#9aa58e;line-height:1.8}@media(max-width:850px){.login-page{grid-template-columns:1fr}.login-story{padding:25px 30px}.login-story>div:nth-child(2),.login-story footer{display:none}.login-form{padding:40px 25px}}
</style>
